    const subtype = asString(event.subtype);
    if (subtype !== undefined && subtype.length > 0 && subtype !== "file_share") {
        return null;
    }
    const botId = asString(event.bot_id);
    if (botId !== undefined && botId.length > 0) {
        return null;
    }
