/** `user_*` is whoever wrote the message, person or bot; `self_*` is the agent reading it. */
export function formatSlackContextBlock(args) {
    const lines = ["<slack_context>", `user_id: ${args.userId}`];
    if (args.userName !== undefined) {
        lines.push(`user_name: ${args.userName}`);
    }
    if (args.userTz !== undefined) {
        lines.push(`user_tz: ${args.userTz}`);
    }
    if (args.userIsBot === true) {
        lines.push("user_is_bot: true");
    }
    if (args.userBotId !== undefined) {
        lines.push(`user_bot_id: ${args.userBotId}`);
    }
    lines.push(`channel_id: ${args.channelId}`);
    lines.push(`thread_ts: ${args.threadTs}`);
    if (args.teamId !== undefined) {
        lines.push(`team_id: ${args.teamId}`);
    }
    if (args.selfUserId !== undefined) {
        lines.push(`self_user_id: ${args.selfUserId}`);
    }
    if (args.selfName !== undefined) {
        lines.push(`self_name: ${args.selfName}`);
    }
    lines.push("</slack_context>");
    return lines.join("\n");
}
